# Terraform Module: `app-infra`

Provisions an S3 bucket (versioned + encrypted + private), an RDS PostgreSQL instance (deletion protection, encrypted, private), and an IAM role for service accounts (IRSA/OIDC trust, least privilege). DB connection string is generated and stored in Secrets Manager — never in Git.

> **Scope note:** the EKS cluster and CloudFront/ACM parts of the canonical spine are out of scope for this task (the module exposes `oidc_provider_arn`/`oidc_subject` as inputs so it composes with whatever cluster module you use). Everything below is complete and applyable on its own.

```
.
├── main.tf                 # root: provider + module wiring
├── variables.tf
├── outputs.tf
├── backend.tf
├── dev.tfvars
├── prod.tfvars
└── modules/
    └── app-infra/
        ├── versions.tf
        ├── variables.tf
        ├── locals.tf
        ├── s3.tf
        ├── s3_replication.tf
        ├── rds.tf
        ├── iam.tf
        └── outputs.tf
```

---

## `modules/app-infra/versions.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source                = "hashicorp/aws"
      version               = "~> 5.40"
      configuration_aliases = [aws.replica]
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}
```

The module always declares the `aws.replica` alias; when replication is disabled it is simply unused (pass the primary provider).

---

## `modules/app-infra/variables.tf`

```hcl
variable "name" {
  description = "Application name, used as the resource name prefix."
  type        = string

  validation {
    condition     = can(regex("^[a-z][a-z0-9-]{1,20}$", var.name))
    error_message = "name must be lowercase alphanumeric/hyphen, 2-21 chars."
  }
}

variable "environment" {
  description = "Environment name. Drives sizing defaults and guardrails."
  type        = string

  validation {
    condition     = contains(["dev", "prod"], var.environment)
    error_message = "environment must be one of: dev, prod."
  }
}

variable "tags" {
  description = "Additional tags applied to every resource."
  type        = map(string)
  default     = {}
}

# ---------------------------------------------------------------- networking

variable "vpc_id" {
  description = "VPC in which the RDS instance lives."
  type        = string
}

variable "database_subnet_ids" {
  description = "Private subnet IDs for the DB subnet group (>= 2 AZs)."
  type        = list(string)

  validation {
    condition     = length(var.database_subnet_ids) >= 2
    error_message = "At least two subnets in distinct AZs are required."
  }
}

variable "db_ingress_cidrs" {
  description = "CIDR blocks permitted to reach PostgreSQL on 5432."
  type        = list(string)
  default     = []
}

variable "db_ingress_security_group_ids" {
  description = "Security groups permitted to reach PostgreSQL on 5432 (preferred over CIDRs)."
  type        = list(string)
  default     = []
}

# ----------------------------------------------------------------------- s3

variable "bucket_name" {
  description = "Bucket name. Defaults to \"<name>-<environment>-assets-<account_id>\"."
  type        = string
  default     = null
}

variable "kms_key_arn" {
  description = "Customer-managed KMS key for S3 + RDS. Null uses AES-256 (S3) and the AWS-managed RDS key."
  type        = string
  default     = null
}

variable "enable_replication" {
  description = "Enable cross-region replication of the assets bucket."
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "Destination region for cross-region replication."
  type        = string
  default     = "us-west-2"
}

variable "noncurrent_version_expiration_days" {
  description = "Days before noncurrent object versions are expired."
  type        = number
  default     = 90
}

# ---------------------------------------------------------------------- rds

variable "db_instance_class" {
  description = "RDS instance class."
  type        = string
  default     = "db.t3.micro"
}

variable "db_allocated_storage" {
  description = "Allocated storage in GiB."
  type        = number
  default     = 20
}

variable "db_max_allocated_storage" {
  description = "Upper bound for storage autoscaling in GiB. 0 disables autoscaling."
  type        = number
  default     = 100
}

variable "db_engine_version" {
  description = "PostgreSQL engine version."
  type        = string
  default     = "16.3"
}

variable "db_name" {
  description = "Initial database name."
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Master username."
  type        = string
  default     = "appadmin"
}

variable "db_multi_az" {
  description = "Deploy the RDS instance across multiple AZs."
  type        = bool
  default     = false
}

variable "db_backup_retention_days" {
  description = "Automated backup retention in days (spec floor: 7)."
  type        = number
  default     = 7

  validation {
    condition     = var.db_backup_retention_days >= 7
    error_message = "Backup retention must be >= 7 days."
  }
}

variable "db_password" {
  description = <<-EOT
    Master password. Leave null (recommended) to have Terraform generate one.
    If supplied, it must come from an encrypted source (SOPS-decrypted tfvars,
    Vault, etc.) and never a plaintext file in Git.
  EOT
  type        = string
  default     = null
  sensitive   = true
}

# ---------------------------------------------------------------------- iam

variable "oidc_provider_arn" {
  description = "IAM OIDC provider ARN of the EKS cluster. Null creates no OIDC trust."
  type        = string
  default     = null
}

variable "oidc_provider_url" {
  description = "OIDC issuer URL without the https:// scheme, e.g. oidc.eks.eu-central-1.amazonaws.com/id/ABC123."
  type        = string
  default     = null
}

variable "service_account_namespace" {
  description = "Kubernetes namespace of the service account allowed to assume the role."
  type        = string
  default     = "default"
}

variable "service_account_name" {
  description = "Kubernetes service account name allowed to assume the role."
  type        = string
  default     = "app"
}

variable "create_iam_user" {
  description = "Create a programmatic-access IAM user. Intended for dev only; refused in prod."
  type        = bool
  default     = false
}
```

---

## `modules/app-infra/locals.tf`

```hcl
data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

locals {
  is_prod = var.environment == "prod"
  prefix  = "${var.name}-${var.environment}"

  bucket_name = coalesce(
    var.bucket_name,
    "${local.prefix}-assets-${data.aws_caller_identity.current.account_id}",
  )

  replica_bucket_name = "${local.bucket_name}-replica"

  use_kms      = var.kms_key_arn != null
  create_oidc  = var.oidc_provider_arn != null && var.oidc_provider_url != null
  oidc_subject = "system:serviceaccount:${var.service_account_namespace}:${var.service_account_name}"

  tags = merge(
    {
      Application = var.name
      Environment = var.environment
      ManagedBy   = "terraform"
      Module      = "app-infra"
    },
    var.tags,
  )
}

# --- Guardrails enforced at plan time -------------------------------------

resource "terraform_data" "prod_guardrails" {
  lifecycle {
    precondition {
      condition     = !local.is_prod || !var.create_iam_user
      error_message = "Long-lived IAM users with static keys are not permitted in prod; use the OIDC role."
    }
    precondition {
      condition     = !local.is_prod || local.create_oidc
      error_message = "prod requires oidc_provider_arn and oidc_provider_url for the service-account role."
    }
    precondition {
      condition     = !local.is_prod || var.db_multi_az
      error_message = "prod requires db_multi_az = true."
    }
    precondition {
      condition     = !local.is_prod || var.enable_replication
      error_message = "prod requires cross-region replication of the assets bucket."
    }
  }
}
```

