## `modules/app-infra/iam.tf`

```hcl
# --- least-privilege application policy ------------------------------------

data "aws_iam_policy_document" "app" {
  statement {
    sid       = "ListAssetsBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = [aws_s3_bucket.assets.arn]
  }

  statement {
    sid    = "ReadWriteAssets"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
    ]
    resources = ["${aws_s3_bucket.assets.arn}/*"]
  }

  statement {
    sid       = "ReadDatabaseSecret"
    effect    = "Allow"
    actions   = ["secretsmanager:GetSecretValue", "secretsmanager:DescribeSecret"]
    resources = [aws_secretsmanager_secret.db.arn]
  }

  dynamic "statement" {
    for_each = local.use_kms ? [1] : []

    content {
      sid       = "UseDataKey"
      effect    = "Allow"
      actions   = ["kms:Decrypt", "kms:GenerateDataKey"]
      resources = [var.kms_key_arn]

      condition {
        test     = "StringEquals"
        variable = "kms:ViaService"
        values = [
          "s3.${data.aws_region.current.name}.amazonaws.com",
          "secretsmanager.${data.aws_region.current.name}.amazonaws.com",
        ]
      }
    }
  }
}

resource "aws_iam_policy" "app" {
  name        = "${local.prefix}-app"
  description = "Least-privilege access to ${local.prefix} assets and DB secret"
  policy      = data.aws_iam_policy_document.app.json
  tags        = local.tags
}

# --- IRSA role (OIDC trust) ------------------------------------------------

data "aws_iam_policy_document" "irsa_assume" {
  count = local.create_oidc ? 1 : 0

  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = [local.oidc_subject]
    }

    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "app" {
  count = local.create_oidc ? 1 : 0

  name                 = "${local.prefix}-app"
  description          = "Service-account role for ${local.prefix}"
  assume_role_policy   = data.aws_iam_policy_document.irsa_assume[0].json
  max_session_duration = 3600
  tags                 = local.tags
}

resource "aws_iam_role_policy_attachment" "app" {
  count = local.create_oidc ? 1 : 0

  role       = aws_iam_role.app[0].name
  policy_arn = aws_iam_policy.app.arn
}

# --- optional programmatic user (dev only; blocked in prod by precondition) --

resource "aws_iam_user" "app" {
  count = var.create_iam_user ? 1 : 0

  name = "${local.prefix}-app"
  path = "/service/"
  tags = local.tags
}

resource "aws_iam_user_policy_attachment" "app" {
  count = var.create_iam_user ? 1 : 0

  user       = aws_iam_user.app[0].name
  policy_arn = aws_iam_policy.app.arn
}

resource "aws_iam_access_key" "app" {
  count = var.create_iam_user ? 1 : 0

  user = aws_iam_user.app[0].name
}
```

---

## `modules/app-infra/outputs.tf`

```hcl
output "bucket_id" {
  description = "Name of the assets bucket."
  value       = aws_s3_bucket.assets.id
}

output "bucket_arn" {
  description = "ARN of the assets bucket."
  value       = aws_s3_bucket.assets.arn
}

output "replica_bucket_arn" {
