## Root module

### `backend.tf`

```hcl
terraform {
  required_version = ">= 1.5.0"

  # Workspace-keyed state: dev and prod live at
  #   env:/dev/app-infra/terraform.tfstate
  #   env:/prod/app-infra/terraform.tfstate
  # Changing prod cannot touch dev state.
  backend "s3" {
    bucket         = "acme-terraform-state"
    key            = "app-infra/terraform.tfstate"
    region         = "eu-central-1"
    dynamodb_table = "acme-terraform-locks"
    encrypt        = true
  }
}
```

### `main.tf`

```hcl
provider "aws" {
  region = var.region

  default_tags {
    tags = {
      Workspace = terraform.workspace
    }
  }
}

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

locals {
  environment = terraform.workspace
}

# Refuse to apply from the `default` workspace.
resource "terraform_data" "workspace_guard" {
  lifecycle {
    precondition {
      condition     = contains(["dev", "prod"], terraform.workspace)
      error_message = "Select a workspace first: terraform workspace select dev|prod."
    }
    precondition {
      condition     = terraform.workspace == var.environment
      error_message = "Workspace '${terraform.workspace}' does not match var.environment '${var.environment}'. Wrong tfvars file?"
    }
  }
}

module "app_infra" {
  source = "./modules/app-infra"

  providers = {
    aws         = aws
    aws.replica = aws.replica
  }

  name        = var.name
  environment = var.environment
  tags        = var.tags

  vpc_id                        = var.vpc_id
  database_subnet_ids           = var.database_subnet_ids
  db_ingress_security_group_ids = var.db_ingress_security_group_ids

  kms_key_arn        = var.kms_key_arn
  enable_replication = var.enable_replication
  replica_region     = var.replica_region

  db_instance_class        = var.db_instance_class
  db_allocated_storage     = var.db_allocated_storage
  db_multi_az              = var.db_multi_az
  db_backup_retention_days = var.db_backup_retention_days

  oidc_provider_arn         = var.oidc_provider_arn
  oidc_provider_url         = var.oidc_provider_url
  service_account_namespace = var.service_account_namespace
  service_account_name      = var.service_account_name
  create_iam_user           = var.create_iam_user
}
```

